add_action('customize_register',function($c){$c->add_panel('rzzlaw',['title'=>'RZZ LAW','priority'=>25]);foreach(rzz_controls() as $group=>$section){$c->add_section('rzz_'.$group,['title'=>$section[0],'panel'=>'rzzlaw']);foreach($section[1] as $key=>$field){$id='rzz_'.$key;$sanitize=match($field[2]){'color'=>'sanitize_hex_color','email'=>'sanitize_email','url','image'=>'esc_url_raw','html'=>'wp_kses_post','textarea'=>'sanitize_textarea_field',default=>'sanitize_text_field'};$c->add_setting($id,['default'=>$field[1],'sanitize_callback'=>$sanitize]);$args=['label'=>$field[0],'section'=>'rzz_'.$group,'type'=>$field[2]==='html'?'textarea':$field[2]];if($field[2]==='image')$c->add_control(new WP_Customize_Image_Control($c,$id,$args));elseif($field[2]==='color')$c->add_control(new WP_Customize_Color_Control($c,$id,$args));else $c->add_control($id,$args);}if(in_array($group,['hero','expertise','why','team','voices','faq','contact','map'])){$id='rzz_show_'.$group;$c->add_setting($id,['default'=>true,'sanitize_callback'=>function($v){return(bool)$v;}]);$c->add_control($id,['label'=>'Show on homepage','type'=>'checkbox','section'=>'rzz_'.$group]);}}});
add_action('wp_head',function(){$color=sanitize_hex_color(rzz_setting('primary','#1d3d34'));if($color)echo '<style>:root{--primary:'.esc_html($color).'}</style>';});
